:Hepatitis owl:equivalentClass [
  owl:intersectionOf ( :Inflammation
    [ a owl:Restriction ;
      owl:onProperty :hasSite ;
      owl:someValuesFrom :Liver ] ) ] .

:MI a skos:Concept ;
  skos:prefLabel "심근경색"@ko ;
  skos:altLabel "심장마비"@ko, "MI"@en ;
  skos:broader :IschemicHeartDisease ;
  skos:related :Troponin .
